create table if not exists audience_forms (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, name text not null, form_type text not null, fields jsonb not null default '[]'::jsonb, status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists audience_segments (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, name text not null, rules jsonb not null default '{}'::jsonb, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists audience_subscribers (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, email text not null, name text, source text, status text not null default 'subscribed', tags jsonb not null default '[]'::jsonb, attributes jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists audience_events (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, subscriber_id uuid, event_type text not null, source text, metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now());
create index if not exists audience_subscribers_workspace_email_idx on audience_subscribers(workspace_id,email);
create index if not exists audience_events_workspace_time_idx on audience_events(workspace_id,occurred_at desc);